import numpy as np
import pandas as pd


TARGET_COLUMN = 'target'


def gini(y):
    """Gini impurity."""
    if len(y) == 0:
        return 0.0
    p = y.mean()
    return 2 * p * (1 - p)


def best_split(X, y, n_features=None, rng=None):
    """Find best split for a node."""
    n, d = X.shape
    if n_features is None:
        n_features = d
    if rng is not None:
        feat_indices = rng.choice(d, n_features, replace=False)
    else:
        feat_indices = np.arange(d)

    best_gain = -1
    best_feat = None
    best_thresh = None
    g0 = gini(y)

    for fi in feat_indices:
        vals = X[:, fi]
        thresholds = np.percentile(vals, np.linspace(10, 90, 10))
        for thresh in thresholds:
            left = y[vals <= thresh]
            right = y[vals > thresh]
            if len(left) == 0 or len(right) == 0:
                continue
            gain = g0 - (len(left)/n) * gini(left) - (len(right)/n) * gini(right)
            if gain > best_gain:
                best_gain = gain
                best_feat = fi
                best_thresh = thresh

    return best_feat, best_thresh, best_gain


class DecisionTree:
    def __init__(self, max_depth=5, min_samples_leaf=10, n_features=None, rng=None):
        self.max_depth = max_depth
        self.min_samples_leaf = min_samples_leaf
        self.n_features = n_features
        self.rng = rng
        self.tree = None

    def fit(self, X, y):
        self.tree = self._build(X, y, depth=0)

    def _build(self, X, y, depth):
        if depth >= self.max_depth or len(y) < 2 * self.min_samples_leaf:
            return y.mean()

        feat, thresh, gain = best_split(X, y, self.n_features, self.rng)
        if feat is None or gain <= 0:
            return y.mean()

        left_mask = X[:, feat] <= thresh
        right_mask = ~left_mask

        if left_mask.sum() < self.min_samples_leaf or right_mask.sum() < self.min_samples_leaf:
            return y.mean()

        return {
            'feat': feat,
            'thresh': thresh,
            'left': self._build(X[left_mask], y[left_mask], depth + 1),
            'right': self._build(X[right_mask], y[right_mask], depth + 1),
        }

    def predict_proba(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])

    def _predict_one(self, x, node):
        if not isinstance(node, dict):
            return node
        if x[node['feat']] <= node['thresh']:
            return self._predict_one(x, node['left'])
        return self._predict_one(x, node['right'])


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Random Forest classifier."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
    X_train = train[feature_cols].values.astype(np.float64)
    y_train = train[TARGET_COLUMN].values.astype(np.float64)
    X_test = test[feature_cols].values.astype(np.float64)

    n, d = X_train.shape
    n_trees = 50
    max_depth = 6
    n_features = int(np.sqrt(d))
    sample_frac = 0.8

    probs = np.zeros(len(X_test))
    for i in range(n_trees):
        rng = np.random.default_rng(i)
        idx = rng.choice(n, int(n * sample_frac), replace=True)
        tree = DecisionTree(max_depth=max_depth, min_samples_leaf=20,
                            n_features=n_features, rng=rng)
        tree.fit(X_train[idx], y_train[idx])
        probs += tree.predict_proba(X_test)

    probs /= n_trees
    preds = (probs >= 0.5).astype(int)
    pd.DataFrame({"prediction": preds}).to_csv(output_csv, index=False)

